   311	/* Parse a string representing a process number or a set of processes. It must
   312	 * be "all", "odd", "even", a number between 1 and <max> or a range with
   313	 * two such numbers delimited by a dash ('-'). On success, it returns
   314	 * 0. otherwise it returns 1 with an error message in <err>.
   315	 *
   316	 * Note: this function can also be used to parse a thread number or a set of
   317	 * threads.
   318	 */
   319	int parse_process_number(const char *arg, unsigned long *proc, int max, int *autoinc, char **err)
   320	{
   321	        if (autoinc) {
   322	                *autoinc = 0;
   323	                if (strncmp(arg, "auto:", 5) == 0) {
   324	                        arg += 5;
   325	                        *autoinc = 1;
   326	                }
   327	        }
   328	
   329	        if (strcmp(arg, "all") == 0)
   330	                *proc |= ~0UL;
   331	        else if (strcmp(arg, "odd") == 0)
   332	                *proc |= ~0UL/3UL; /* 0x555....555 */
   333	        else if (strcmp(arg, "even") == 0)
   334	                *proc |= (~0UL/3UL) << 1; /* 0xAAA...AAA */
   335	        else {
   336	                const char *p, *dash = NULL;
   337	                unsigned int low, high;
   338	
   339	                for (p = arg; *p; p++) {
   340	                        if (*p == '-' && !dash)
   341	                                dash = p;
   342	                        else if (!isdigit((unsigned char)*p)) {
   343	                                memprintf(err, "'%s' is not a valid number/range.", arg);
   344	                                return -1;
   345	                        }
   346	                }
   347	
   348	                low = high = str2uic(arg);
   349	                if (dash)
   350	                        high = ((!*(dash+1)) ? max : str2uic(dash + 1));
   351	
   352	                if (high < low) {
   353	                        unsigned int swap = low;
   354	                        low  = high;
   355	                        high = swap;
   356	                }
   357	
   358	                if (low < 1 || low > max || high > max) {
   359	                        memprintf(err, "'%s' is not a valid number/range."
   360	                                  " It supports numbers from 1 to %d.\n",
   361	                                  arg, max);
   362	                        return 1;
   363	                }
   364	
   365	                for (;low <= high; low++)
   366	                        *proc |= 1UL << (low-1);
   367	        }
   368	        *proc &= ~0UL >> (LONGBITS - max);
   369	
   370	        return 0;
   371	}
