   373	#ifdef USE_CPU_AFFINITY
   374	/* Parse cpu sets. Each CPU set is either a unique number between 0 and
   375	 * <LONGBITS> or a range with two such numbers delimited by a dash
   376	 * ('-'). Multiple CPU numbers or ranges may be specified. On success, it
   377	 * returns 0. otherwise it returns 1 with an error message in <err>.
   378	 */
   379	unsigned long parse_cpu_set(const char **args, unsigned long *cpu_set, char **err)
   380	{
   381	        int cur_arg = 0;
   382	
   383	        *cpu_set = 0;
   384	        while (*args[cur_arg]) {
   385	                char        *dash;
   386	                unsigned int low, high;
   387	
   388	                if (!isdigit((unsigned char)*args[cur_arg])) {
   389	                        memprintf(err, "'%s' is not a CPU range.\n", args[cur_arg]);
   390	                        return -1;
   391	                }
   392	
   393	                low = high = str2uic(args[cur_arg]);
   394	                if ((dash = strchr(args[cur_arg], '-')) != NULL)
   395	                        high = ((!*(dash+1)) ? LONGBITS-1 : str2uic(dash + 1));
   396	
   397	                if (high < low) {
   398	                        unsigned int swap = low;
   399	                        low = high;
   400	                        high = swap;
   401	                }
   402	
   403	                if (high >= LONGBITS) {
   404	                        memprintf(err, "supports CPU numbers from 0 to %d.\n", LONGBITS - 1);
   405	                        return 1;
   406	                }
   407	
   408	                while (low <= high)
   409	                        *cpu_set |= 1UL << low++;
   410	
   411	                cur_arg++;
   412	        }
   413	        return 0;
   414	}
